mapper.select:
/*AuthMapper.findRefreshToken*/
SELECT id as refreshTokenId,
       account_id,
       token,
       expires_at
FROM auth.refresh_token
WHERE account_id = #{accountId}
  AND token = #{refreshToken}

/*AuthMapper.existsByUserName*/
SELECT EXISTS(SELECT 1
              FROM auth.account
              WHERE user_name = #{userName}
                AND auth_role != 'LEFT')

/*AuthMapper.findPasswordHash*/
SELECT password_hash
FROM auth.account
WHERE id = #{accountId}

mapper.update:
/*AuthMapper.updateUserName*/
UPDATE
  auth.account
SET user_name  = #{userName},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{accountId}

/*AuthMapper.updatePassword*/
UPDATE
  auth.account
SET password_hash = #{passwordHash},
    updated_at    = CURRENT_TIMESTAMP
WHERE id = #{accountId}
